import {readSkeletalTrackKeys} from './skeletal-track-keys.js';
export class SkeletalTrackEditor {
 constructor(element,doc,hooks){Object.assign(this,{element,doc,hooks});if(!doc.view.skeletalTrackKeys||typeof doc.view.skeletalTrackKeys!=='object'||Array.isArray(doc.view.skeletalTrackKeys))doc.view.skeletalTrackKeys={};this.view=doc.view.skeletalTrackKeys;if(typeof this.view.track!=='string')this.view.track='';for(const key of ['offset','channelOffset'])if(!Number.isSafeInteger(this.view[key])||this.view[key]<0)this.view[key]=0;this.render();}
 node(tag,text){const e=this.element.ownerDocument.createElement(tag);if(text!==undefined)e.textContent=text;return e;}
 button(text,action,edit=false){const e=this.node('button',text);e.type='button';e.onclick=action;if(edit)this.controls.push(e);return e;}
 input(label,value,change,type='number'){const wrap=this.node('label',label),input=this.node('input');input.type=type;input.value=String(value);input.step='any';input.setAttribute('aria-label',label);input.onchange=change;wrap.append(input);this.controls.push(input);return{wrap,input};}
 setBusy(value){this.busy=!!value;for(const control of this.controls||[])control.disabled=this.busy||!!this.hooks.running?.();}
 async submit(params,create=false){if(this.disposed||this.busy||this.hooks.running?.())return;try{if(this.doc.data!==this.source){this.render();throw Error('골격 트랙이 바뀌었어요. 최신 키를 확인하세요.');}this.setBusy(true);await this.hooks.edit(params,create,this.source);}catch(error){this.hooks.error(error.message);if(!this.disposed)this.message.textContent=error.message;}finally{if(!this.disposed)this.setBusy(false);}}
 render(){
  const e=this.element,d=this.doc.data;this.source=d;this.controls=[];e.replaceChildren();e.classList.add('skeletal-track-editor');const bar=this.node('div');bar.className='skeletal-track-toolbar';const select=this.node('select');select.setAttribute('aria-label','골격 트랙');if(!d.tracks.some(t=>t.name===this.view.track)){this.view.track=d.tracks[0]?.name||'';this.view.offset=0;this.view.channelOffset=0;}for(const track of d.tracks){const option=this.node('option',track.name);option.value=track.name;select.append(option);}select.value=this.view.track;select.onchange=()=>{this.view.track=select.value;this.view.offset=0;this.view.channelOffset=0;this.render();};bar.append(select);e.append(bar);
  const create=this.node('div');create.className='skeletal-track-toolbar';const path=this.input('새 트랙 경로','',null,'text'),stride=this.input('모프 채널 수',1);path.input.placeholder='Hips.position';stride.input.min=1;stride.input.max=256;create.append(path.wrap,stride.wrap,this.button('트랙 추가',()=>this.submit({track:path.input.value,stride:Number(stride.input.value)},true),true));e.append(create);
  this.message=this.node('output');this.message.setAttribute('role','status');e.append(this.message);if(!this.view.track){this.message.textContent='골격 트랙이 없어요.';this.setBusy(false);return;}
  const t=d.tracks.find(t=>t.name===this.view.track),count=t.times.length;this.view.offset=Math.min(this.view.offset,Math.max(0,Math.floor((count-1)/32)*32));const strideCount=t.values.length/count;if(this.view.channelOffset>=strideCount)this.view.channelOffset=0;const page=readSkeletalTrackKeys(d,{track:t.name,offset:this.view.offset,limit:32,channelOffset:this.view.channelOffset,channelLimit:4});
  const mode=this.node('select');mode.setAttribute('aria-label','골격 트랙 보간');const modes=[['step','계단',2300],['linear','선형',2301],...t.type==='quaternion'?[]:[['smooth','Smooth',2302]]];if(!modes.some(row=>row[2]===page.interpolation)){const option=this.node('option','지원하지 않는 보간 · 선택 필요');option.value='';mode.append(option);}for(const[value,label,number]of modes){const option=this.node('option',label);option.value=value;mode.append(option);if(number===page.interpolation)mode.value=value;}mode.onchange=()=>this.submit({track:t.name,interpolation:mode.value});this.controls.push(mode);bar.append(mode);
  const time=this.input('추가 시간 (초)',this.hooks.time?.()||0);time.input.min=0;time.input.max=d.duration;bar.append(time.wrap,this.button('시간에 키 추가',()=>this.submit({track:t.name,insert:[{time:Number(time.input.value)}]}),true));
  const pager=this.node('div');pager.className='skeletal-track-toolbar';const previous=this.button('이전 키',()=>{this.view.offset=Math.max(0,this.view.offset-32);this.render();}),next=this.button('다음 키',()=>{this.view.offset+=32;this.render();});previous.disabled=!this.view.offset;next.disabled=page.nextOffset===null;pager.append(previous,this.node('span',(page.offset+1)+'–'+(page.offset+page.items.length)+' / '+page.total),next);if(page.stride>4){const left=this.button('이전 채널',()=>{this.view.channelOffset=Math.max(0,this.view.channelOffset-4);this.render();}),right=this.button('다음 채널',()=>{this.view.channelOffset+=4;this.render();});left.disabled=!this.view.channelOffset;right.disabled=page.nextChannel===null;pager.append(left,this.node('span','채널 '+this.view.channelOffset+'–'+(this.view.channelOffset+page.channels-1)),right);}e.append(pager);
  const table=this.node('table'),body=this.node('tbody');table.append(body);for(const row of page.items){const tr=this.node('tr');tr.append(this.node('th',String(row.index)));const timeCell=this.node('td'),timeInput=this.input('키 '+row.index+' 시간 (초)',row.time);timeInput.input.min=0;timeInput.input.max=d.duration;timeInput.input.onchange=()=>this.submit({track:t.name,edits:[{index:row.index,time:Number(timeInput.input.value)}]});timeCell.append(timeInput.wrap);tr.append(timeCell);for(let c=0;c<page.channels;c++){const channel=page.channelOffset+c,unit=/\.rotation(?:\[[^\]]+\])?$/.test(t.name)?' (rad)':/\.position(?:\[[^\]]+\])?$/.test(t.name)?' (m)':'',label=t.type==='number'?'값 '+channel:'XYZW'[channel],cell=this.node('td'),field=this.input('키 '+row.index+' '+label+unit,row.values[c]);field.input.onchange=()=>{const values=t.values.slice(row.index*page.stride,(row.index+1)*page.stride);values[channel]=Number(field.input.value);return this.submit({track:t.name,edits:[{index:row.index,values}]});};cell.append(field.wrap);tr.append(cell);}const actions=this.node('td'),remove=this.button('삭제',()=>this.submit({track:t.name,remove:[row.index]}),true);remove.setAttribute('aria-label','키 '+row.index+' 삭제');actions.append(remove);tr.append(actions);body.append(tr);}e.append(table);this.setBusy(false);
 }
 dispose(){this.disposed=true;this.controls=[];}
}
